-- game.ReplicatedStorage.Shared.Effects.PVE.Augments.Wave4.HairpinSnap
local v1 = game:GetService("ReplicatedStorage")
local v_u_2 = require(v1.Client.Features.Audio.AudioController)
local v_u_3 = require(v1.Shared.Effects.PVE.Augments.AugmentVFX)
return function(p4)
	-- upvalues: (copy) v_u_3, (copy) v_u_2
	local v5 = v_u_3.Root(p4)
	if v5 then
		local v6, v7 = v_u_3.Hand(p4, "Right")
		local v8
		if v6 then
			v8 = v6.CFrame * v7
		else
			v8 = v5.CFrame
		end
		local v9 = v_u_3.Template("Hairpin", "Snap")
		if v9 then
			v_u_3.Burst(v9, v8, v6 or v5)
		end
		v_u_2:PlaySoundAtPosition("HairpinSnap", v8.Position)
	end
end











