			else
				return ("%*h"):format(v5)
			end
		elseif v4 >= 60 then
			local v7 = v4 // 60
			local v8 = v4 % 60
			if v8 > 0 then
				return ("%*m %*s"):format(v7, v8)
			else
				return ("%*m"):format(v7)
			end
		else
			return ("%*s"):format(v4)
		end
	end,
	["Countdown"] = function(p9) -- name: Countdown
		local v10 = tonumber(p9) or 0
		local v11 = math.floor(v10)
		local v12 = math.max(v11, 0)
		if v12 >= 3600 then
